t s5.is_cycle) select (select coalesce(array_agg((_edge.id, _edge.start_id, _edge.end_id, _edge.kind_id, _edge.properties)::edgecomposite order by _path.ordinality), array []::edgecomposite[]) from unnest(s5.path) with ordinality as _path(id, ordinality) join edge _edge on _edge.id = _path.id) as e1, s5.path as ep1, (n0.id, n0.kind_ids, n0.properties)::nodecomposite as n0, (n2.id, n2.kind_ids, n2.properties)::nodecomposite as n2 from s0, s5 join lateral (select n0.id, n0.kind_ids, n0.properties from node n0 where n0.id = s5.root_id offset 0) n0 on true join lateral (select n2.id, n2.kind_ids, n2.properties from node n2 where n2.id = s5.next_id offset 0) n2 on true where (n2.id = n0.id) and (s0.n0).id = s5.root_id), s6 as (select s0.n0 as n0, s4.e1 as e1, s4.ep1 as ep1, s4.n2 as n2 from s0 left outer join s4 on (s0.n0 is not distinct from s4.n0)) select s6.n0 as n0, 1 / (1 - count(distinct s6.n2)::int8) as i1 from s6 group by n0), s7 as (with recursive s8_seed(root_id) as not materialized (select distinct (s3.n0).id as root_id from s3), s8(root_id, next_id, depth, satisfied, is_cycle, path) as (select e2.end_id, e2.start_id, 1, false, e2.end_id = e2.start_id, array [e2.id] from s8_seed join edge e2 on e2.end_id = s8_seed.root_id where e2.kind_id = any (array [101, 134]::int2[]) union all select s8.root_id, e2.start_id, s8.depth + 1, false, false, e2.id || s8.path from s8 join lateral (select e2.id, e2.start_id, e2.end_id, e2.kind_id, e2.properties from edge e2 where e2.end_id = s8.next_id and e2.id != all (s8.path) and e2.kind_id = any (array [101, 134]::int2[]) offset 0) e2 on true where not s8.is_cycle) select (select coalesce(array_agg((_edge.id, _edge.start_id, _edge.end_id, _edge.kind_id, _edge.properties)::edgecomposite order by _path.ordinality), array []::edgecomposite[]) from unnest(s8.path) with ordinality as _path(id, ordinality) join edge _edge on _edge.id = _path.id) as e2, s8.path as ep2, s3.i1 as i1, (n0.id, n0.kind_ids, n0.properties)::nodecomposite a